component.css:
[cmsrt] h1,
[cmsrt] h2,
[cmsrt] h3,
[cmsrt] h4,
[cmsrt] h5,
[cmsrt] h6 {
  font-weight: var(--h-fw);
  letter-spacing: var(--h-ls);
  color: var(--text);
  margin-top: 32px;
  margin-bottom: 8px;
}

[cmsrt] h1 { font-size: var(--h-fs); }
[cmsrt] h2 { font-size: var(--he-fs); }
[cmsrt] h3 { font-size: var(--hea-fs); }
[cmsrt] h4 { font-size: var(--head-fs); }

[cmsrt] p {
  margin-bottom: 16px;
}

[cmsrt] a {
  color: var(--text);
  text-decoration: underline;
}

[cmsrt] ul,
[cmsrt] ol {
  margin-bottom: 16px;
  padding-left: 24px;
}

[cmsrt] li {
  margin-bottom: 8px;
}

[cmsrt] blockquote {
  border-left: 3px solid var(--border);
  padding-left: 16px;
  margin: 24px 0;
  color: var(--muted);
}

[cmsrt] img {
  max-width: 100%;
  height: auto;
  border-radius: 8px;
  margin: 24px 0;
}
